WITH RecursiveRelatedPosts AS (
    SELECT PL.PostId, PL.RelatedPostId, 1 AS Depth
    FROM PostLinks PL
    WHERE PL.LinkTypeId = 3 -- Duplicate link type
  UNION ALL
    SELECT R.PostId, PL.RelatedPostId, R.Depth + 1
    FROM RecursiveRelatedPosts R
    JOIN PostLinks PL ON R.RelatedPostId = PL.PostId AND PL.LinkTypeId = 3 AND R.Depth < 5
